  'collaborate-task':()=>ask('Collaborative task','Shared goal','',async task=>{const ids=state.providers.filter(p=>p.enabled&&['claude','codex'].includes(p.kind)).map(p=>p.id);if(!ids.length)throw new Error('Enable a native CLI provider to collaborate.');if(ids.length===1)ids.push(ids[0]);await newChat();let result=await send('You are the coordinator. Create a plan and assign independent review tasks for this shared goal:\n'+task,[ids[0]]);if(!result[0])return;result=await send('You are a specialist. Independently evaluate this shared plan, identify risks and propose concrete improvements.\nGoal: '+task+'\nPlan: '+result[0],ids);if(result.some(value=>!value))throw new Error('Collaboration stopped because a specialist failed.');return send('You are the coordinator. Reconcile both specialist findings into one final plan or solution. Address disagreements and give verification steps.\nGoal: '+task+'\nFindings:\n'+result.join('\n\n'),[ids[0]]);},true),
