async function feedback(id,value) { const chat=structuredClone(currentChat()),m=chat.messages.find(m=>m.id===id);m.feedback=m.feedback===value?'':value;return persistChat(chat); }
function palette() { dialog('Command palette',`<input id="paletteSearch" type="search" placeholder="Type a command…" aria-label="Search commands"><div id="paletteList" class="palette-list"></div>`);const commands=[...sections.map(([key,icon,name])=>[icon+' '+name,'route',key]),['New conversation','new',''],['Temporary conversation','temporary',''],['Open project folder','open-project',''],['Environment setup','env-help','']];const display=q=>$('paletteList').innerHTML=commands.filter(([name])=>name.toLowerCase().includes(q.toLowerCase())).map(([name,action,id])=>button(name,'command',action+':'+id)).join('');display('');$('paletteSearch').oninput=e=>display(e.target.value);$('paletteSearch').focus(); }
actions.command=async key=>{const [action,id]=key.split(':');closeDialog();if(action==='new')return newChat();if(action==='temporary')return newChat(true);return actions[action]?.(id);};
async function parallelDialog() { dialog('Compare providers',`<form id="parallelForm" class="form"><p>Send the same task and conversation context to the selected providers.</p>${state.providers.filter(p=>p.enabled).map(p=>`<label class="check"><input name="${E(p.id)}" type="checkbox" ${['claude','codex'].includes(p.id)?'checked':''}>${E(p.name)}</label>`).join('')}<button class="primary">Send task</button></form>`);$('parallelForm').onsubmit=act(async event=>{event.preventDefault();const ids=[...event.target.elements].filter(i=>i.type==='checkbox'&&i.checked).map(i=>i.name);if(ids.length<2)throw new Error('Select at least two providers.');closeDialog();await api('settings:save',{...state.settings,splitView:true});return send(undefined,ids);}); }
function syncDialog() { const sync=auth.sync||{};dialog('Firebase synchronization',`<p>${E(sync.lastError||'Your workspace changes are synchronized with Cloud Firestore.')}<br>${sync.pending||0} queued change(s). Last sync: ${sync.lastSync?new Date(sync.lastSync).toLocaleString():'Not yet'}</p><div class="card-actions">${button('Sync now','sync-now')}</div>${(sync.conflicts||[]).map(c=>`<div class="card"><h3>${E(c.title)}</h3><p>This record changed on another device. Choose the version to keep.</p><div class="card-actions">${button('Keep this device','sync-local',c.type+':'+c.id)}${button('Use cloud version','sync-remote',c.type+':'+c.id)}</div></div>`).join('')}`); }
actions['sync-now']=async()=>{auth.sync=await api('sync:now');syncDialog();};
for(const choice of ['local','remote'])actions['sync-'+choice]=async key=>{const [type,id]=key.split(':');auth.sync=await api('sync:resolve',{type,id,choice});syncDialog();};
function matchesShortcut(event,shortcut) { const parts=shortcut.toLowerCase().split('+'),key=parts.pop(),code=/^[0-9]$/.test(key)?'Digit'+key:/^[a-z]$/.test(key)?'Key'+key.toUpperCase():({'.':'Period',',':'Comma','/':'Slash','-':'Minus'}[key]);return (event.key.toLowerCase()===key||!!code&&event.code===code)&&!!(event.metaKey||event.ctrlKey)===parts.includes('mod')&&event.shiftKey===parts.includes('shift')&&event.altKey===parts.includes('alt'); }
document.addEventListener('click',act(async event=>{const codeButton=event.target.closest('[data-code-copy]');if(codeButton){await navigator.clipboard.writeText(codeButton.closest('.code-block').querySelector('code').textContent);toast('Code copied.');return;}const link=event.target.closest('[data-external]');if(link){event.preventDefault();await api('app:external',{url:link.href});return;}const target=event.target.closest('[data-action]');if(target){const action=actions[target.dataset.action];if(action)return action(target.dataset.id);}}));
document.addEventListener('contextmenu',act(async event=>{const row=event.target.closest('.history-row'),message=event.target.closest('.message');if(row){event.preventDefault();return actions['chat-menu'](row.querySelector('[data-action=chat]').dataset.id);}if(message){event.preventDefault();const id=message.id.slice(8);dialog('Message actions',`<div class="palette-list">${button('Copy','copy-message',id)}${button('Branch conversation','branch',id)}${button('Save snippet','save-snippet',id)}</div>`);}}));
document.addEventListener('input',event=>{if(event.target.id==='viewSearch'){const cursor=event.target.selectionStart;query=event.target.value;render();$('viewSearch')?.focus();$('viewSearch')?.setSelectionRange(cursor,cursor);}if(event.target.id==='searchInput'){const cursor=event.target.selectionStart;query=event.target.value;renderSearch();$('searchInput').focus();$('searchInput').setSelectionRange(cursor,cursor);}});
document.addEventListener('change',event=>{if(event.target.id==='searchFilter'){semanticResults=null;searchType=event.target.value;renderSearch();}});
$('authForm').onsubmit=async event=>{event.preventDefault();$('authError').textContent='';$('authSubmit').disabled=true;try{auth=await api(signUp?'auth:signUp':'auth:signIn',{email:$('authEmail').value.trim(),password:$('authPassword').value});$('authPassword').value='';render();}catch(error){$('authError').textContent=error.message;}finally{renderAuth();}};
$('authToggle').onclick=()=>{signUp=!signUp;$('authError').textContent='';renderAuth();};$('authReset').onclick=act(async()=>{await api('auth:reset',{email:$('authEmail').value.trim()});toast('If an account exists, a password reset email will arrive shortly.');});
$('firebaseSetup').onclick=act(showEnvHelp);$('publicProgress').onclick=()=>dialog('Feature progress',progressMarkup());$('closeModal').onclick=closeDialog;
$('newChat').onclick=act(()=>newChat());$('temporaryChat').onclick=act(()=>newChat(true));$('send').onclick=act(()=>send());
$('stop').onclick=act(async()=>{await Promise.all([...running.entries()].filter(([,r])=>r.chatId===activeId).map(([requestId])=>api('agent:stop',{requestId})));});
$('attach').onclick=act(async()=>{attached.push(...await api('files:pick'));if(attached.length>state.settings.maxAttachments)attached=attached.slice(0,state.settings.maxAttachments);renderAttachments();});$('attachFolder').onclick=act(async()=>{attached.push(...await api('files:pick',{folder:true}));renderAttachments();});
$('parallel').onclick=act(parallelDialog);$('usePrompt').onclick=()=>navigate('prompts');
$('readResponse').onclick=act(()=>{const content=[...(currentChat()?.messages||[])].reverse().find(m=>m.role==='assistant')?.content;if(!content)return;if(!window.speechSynthesis)throw new Error('Text-to-speech is unavailable on this system.');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(content));});
$('prompt').oninput=event=>{event.target.style.height='auto';event.target.style.height=Math.min(event.target.scrollHeight,190)+'px';};
$('prompt').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&(!event.metaKey&&!event.ctrlKey||state.settings.sendShortcut==='Mod+Enter')){if(state.settings.sendShortcut==='Mod+Enter'&&!event.metaKey&&!event.ctrlKey)return;event.preventDefault();act(()=>send())();}};
$('provider').onchange=act(async()=>{const provider=state.providers.find(p=>p.id===$('provider').value);$('model').value=provider?.model||'';renderModelOptions();await api('settings:save',{...state.settings,defaultProvider:$('provider').value});});
$('projectSwitcher').onchange=event=>{projectId=event.target.value;activeId=null;render();};$('conversationSearch').oninput=renderHistory;$('archiveToggle').onclick=()=>{archived=!archived;$('archiveToggle').classList.toggle('selected',archived);renderHistory();};
$('globalSearch').onclick=()=>{navigate('search');searchType='';$('searchInput').focus();};$('commandPalette').onclick=palette;$('fullscreen').onclick=act(()=>api('app:fullscreen'));
$('collapseSidebar').onclick=act(()=>api('settings:save',{...state.settings,sidebarCollapsed:true}));$('expandSidebar').onclick=act(async()=>{await api('settings:save',{...state.settings,sidebarCollapsed:false});$('sidebar').classList.toggle('mobile-visible');});
$('syncStatus').onclick=syncDialog;
$('account').onclick=()=>{dialog('Your account',`<p>${E(auth.user.email)}<br>${auth.user.emailVerified?'Email verified':'Email verification pending'}<br>${auth.sessionPersistence?'Session protected by OS encryption':'Session is not saved on this device'}</p><div class="palette-list">${!auth.user.emailVerified?button('Send verification email','verify-email')+button('Refresh verification status','refresh-auth'):''}${button('Sign out','sign-out')}</div>`);};
actions['verify-email']=async()=>{await api('auth:verify');toast('Verification email sent.');};actions['refresh-auth']=async()=>{auth=await api('auth:refresh');renderAuth();closeDialog();};actions['sign-out']=async()=>{auth=await api('auth:signOut');state=C.initialState();activeId=null;temporary.clear();running.clear();attached=[];closeDialog();render();};
document.addEventListener('keydown',act(async event=>{if(!auth.user)return;if(event.key==='Escape'&&!$('modal').open){$('sidebar').classList.remove('mobile-visible');return;}for(const [shortcut,handler]of [[state.settings.newChatShortcut,()=>newChat()],[state.settings.paletteShortcut,palette],[state.settings.searchShortcut,()=>{$('globalSearch').click();}],[state.settings.settingsShortcut,()=>navigate('settings')]])if(matchesShortcut(event,shortcut)){event.preventDefault();return handler();}for(const p of state.prompts)if(p.shortcut&&matchesShortcut(event,p.shortcut)){event.preventDefault();return useTemplate(p.id);}}));
let dragging=false;$('sidebarResizer').onpointerdown=event=>{dragging=true;event.target.setPointerCapture(event.pointerId);};$('sidebarResizer').onpointermove=event=>{if(!dragging)return;document.documentElement.style.setProperty('--sidebar-width',Math.max(180,Math.min(420,event.clientX))+'px');};$('sidebarResizer').onpointerup=act(async event=>{if(!dragging)return;dragging=false;await api('settings:save',{...state.settings,sidebarWidth:Math.max(180,Math.min(420,event.clientX))});});$('sidebarResizer').onkeydown=act(async event=>{if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();await api('settings:save',{...state.settings,sidebarWidth:Math.max(180,Math.min(420,state.settings.sidebarWidth+(event.key==='ArrowRight'?10:-10)))});}});
document.addEventListener('dragover',event=>{if(!auth.user)return;event.preventDefault();document.body.classList.add('dragging');});document.addEventListener('dragleave',event=>{if(!event.relatedTarget)document.body.classList.remove('dragging');});document.addEventListener('drop',act(async event=>{event.preventDefault();document.body.classList.remove('dragging');if(!auth.user)return;attached.push(...await window.kairo.attachDroppedFiles(event.dataTransfer.files));renderAttachments();}));
window.kairo.on('auth:changed',value=>{auth=value;if(!auth.user){temporary.clear();running.clear();attached=[];state=C.initialState();activeId=null;renderAttachments();}render();});
window.kairo.on('state:changed',({state:next,sync})=>{const changed=state.revision!==next.revision;state=next;auth.sync=sync;if(changed)scheduleRender();else if(auth.user)renderChrome();});window.kairo.on('provider:health',value=>{health.set(value.id,value);scheduleRender();});window.kairo.on('app:error',error=>toast(error,true));
window.kairo.on('agent:chunk',({requestId,chunk})=>{const r=running.get(requestId);if(!r)return;r.content+=chunk;if(r.chatId!==activeId||streamFrame)return;streamFrame=setTimeout(()=>{streamFrame=null;const host=$('view'),nearBottom=host.scrollHeight-host.scrollTop-host.clientHeight<100;for(const [id,run]of running)if(run.chatId===activeId){const bubble=$('message-'+id)?.querySelector('.bubble');if(bubble)bubble.textContent=run.content;}if(nearBottom)host.scrollTop=host.scrollHeight;},33);});
matchMedia('(prefers-color-scheme: light)').addEventListener('change',applyAppearance);
const sessionStart=Date.now();
(async()=>{try{const initial=await api('app:bootstrap');state=initial.state;auth=initial.auth;features=initial.features;health=new Map(initial.health.map(h=>[h.id,h]));activeId=state.conversations.filter(c=>!c.archived&&(!projectId||c.projectId===projectId)).sort((a,b)=>(b.updatedAt||b.createdAt)-(a.updatedAt||a.createdAt))[0]?.id||null;$('provider').value=state.settings.defaultProvider;$('model').value=state.settings.defaultModel||modelFor(state.settings.defaultProvider);route=state.settings.layout==='review'?'git':state.settings.layout==='project'?'projects':'chat';render();}catch(error){$('authError').textContent=error.message;}})();

const permissionQueue=[];
function showPermission(){const pending=permissionQueue[0];if(!pending){$('permissionModal').close();return;}$('permissionTool').textContent=pending.tool;$('permissionInput').textContent=JSON.stringify(pending.input,null,2);if(!$('permissionModal').open)$('permissionModal').showModal();}
window.kairo.on('agent:permission',request=>{permissionQueue.push(request);showPermission();});
for(const [id,allow]of [['allowPermission',true],['denyPermission',false]])$(id).onclick=act(async()=>{const pending=permissionQueue[0];try{if(pending)await api('agent:permission',{permissionId:pending.permissionId,allow});}finally{permissionQueue.shift();showPermission();}});
$('permissionModal').addEventListener('cancel',event=>{event.preventDefault();$('denyPermission').click();});
let dictating=false;
$('voiceInput').onclick=act(async()=>{if(dictating){await api('speech:stop');return;}await api('speech:start');dictating=true;$('voiceInput').textContent='■';});
window.kairo.on('speech:result',result=>{dictating=false;$('voiceInput').textContent='🎙';if(result.error){toast(result.error,true);return;}$('prompt').value=[$('prompt').value,result.text].filter(Boolean).join(' ');$('prompt').focus();});

window.kairo.on('notification:sound',({dataURL})=>{if(!auth.user)return;const sound=new Audio(dataURL);sound.play().catch(()=>{});});
